import{db,roles,access,modules,visible}from'../store.js';import{icon,card,heading,link,esc,note,empty}from'../components/ui.js';
export function home(){const ts=access[db.role].includes('tasks')?visible():[];const pending=ts.filter(t=>!['已完成','已取消'].includes(t.status));return `<section class="greeting"><p>11月7日 星期六 <span>演示工作日</span></p><h1>${esc(roles[db.role][1])}，工作順利</h1><p>${db.role==='MASTER'?'現場資料、工作記錄，一手掌握。':'按你的工作範圍，跟進每一項交接。'}</p></section><section class="hero"><div class="hero-line">${icon('task')}<span>${db.role==='MASTER'?'我的現場安排':'我的工作摘要'}</span><span class="hero-label">本機演示</span></div><h2>${pending.length?`${pending.length} 項工作待跟進`:'查看業務工作'}</h2><p>${pending[0]?esc(pending[0].customer):'手機查閱已開放，複雜交易請使用 PC。'}</p>${link(pending.length?'查看我的任務':'開啟工作入口',access[db.role][0],'hero-link')}<div class="hero-mark">EC</div></section><div class="stats">${[['待接單',ts.filter(t=>t.status==='待確認').length],['進行中',ts.filter(t=>['待處理','處理中'].includes(t.status)).length],['待確認',ts.filter(t=>t.submitted&&t.status!=='已完成').length]].map(([l,n])=>`<a href="#/${db.role==='TL'?'approvals':access[db.role][0]}"><strong>${n}</strong><span>${l}</span></a>`).join('')}</div>${heading('工作入口')}<div class="module-grid">${access[db.role].map(k=>link(`${icon(modules[k][1])}<span>${modules[k][0]}</span>`,k)).join('')}</div>${pending.length?heading('優先跟進',link('查看全部','tasks'))+pending.slice(0,2).map(t=>card(t)).join(''):note('此身份只顯示目前開放的手機入口；沒有授予新的業務權限。')}`;}
export function profile(){return `<section class="profile"><div class="avatar">${esc(roles[db.role][1].slice(0,1))}</div><h1>${esc(roles[db.role][1])}</h1><p>${esc(roles[db.role][0])} · EC InfoTech</p></section>${heading('評審身份')}<p class="muted">角色切換僅用於原型演示，不是正式登入。</p><button type="button" class="secondary role-select-trigger" data-ui="roles" role="combobox" aria-label="切換評審身份" aria-expanded="false" aria-haspopup="listbox">切換評審身份</button>${heading('本機演示資料')}<section class="panel"><p>操作只儲存在此瀏覽器，與 PC、倉庫通及其他裝置分開。照片與簽名不會傳送。</p>${link('查看消息記錄','messages','row-link')}<button class="danger" data-action="reset">重設手機演示資料</button><p class="muted">會清除本手機原型的草稿、照片與操作記錄，PC 資料不受影響。</p></section>${note('待確認：C-04 階段供料、C-08 缺簽及交付、C-10 整體保養、C-14 組合完成；即時維修後補不重新接受／中單／收款。')}`;}
export function messages(){return `${heading('消息與操作記錄')}<p class="muted">僅顯示本瀏覽器演示操作，沒有對外發送通知。</p>${db.messages.length?db.messages.map((m,i)=>`<button class="message ${m.read?'read':''}" data-message="${i}">${icon('bell')}<span>${esc(m.text)}<small>${m.read?'已讀':'點擊查看消息'}</small></span></button>`).join(''):empty('暫無新的演示消息')}`;}
